export function AboutSection({
  heading = "{{heading}}",
  body = "{{body}}",
  layout = "{{layout}}",
  accent = "{{accent}}",
  showStats = {{showStats}},
}) {
  const wrap = {
    "image-left": { flexDirection: "row" },
    "image-right": { flexDirection: "row-reverse" },
    centered: { flexDirection: "column", textAlign: "center" },
  }[layout] ?? {};
  return (
    <section style={{ display: "flex", gap: 32, alignItems: "center", font: "16px/1.6 system-ui, sans-serif",
      color: "#241430", padding: "40px 24px", background: "#FAF7F2", ...wrap }}>
      <div style={{ flex: "1 1 240px", minHeight: 180, borderRadius: 12,
        background: `linear-gradient(135deg, ${accent}, #FAF7F2)` }} role="img" aria-label="Photo of the team" />
      <div style={{ flex: "1 1 320px" }}>
        <h2 style={{ margin: "0 0 12px", fontSize: 26, fontWeight: 700 }}>{heading}</h2>
        <p style={{ margin: "0 0 16px", color: "#241430cc" }}>{body}</p>
        {showStats && (
          <dl style={{ display: "flex", gap: 24, margin: 0, justifyContent: layout === "centered" ? "center" : "flex-start" }}>
            <div><dt style={{ fontSize: 22, fontWeight: 700, color: accent }}>12</dt><dd style={{ margin: 0, fontSize: 13, color: "#241430aa" }}>Years</dd></div>
            <div><dt style={{ fontSize: 22, fontWeight: 700, color: accent }}>340+</dt><dd style={{ margin: 0, fontSize: 13, color: "#241430aa" }}>Projects</dd></div>
          </dl>
        )}
      </div>
    </section>
  );
}
